editorial:
## Method and reasoning
Add a flag for whether the discount was used. Ordinary edges preserve the flag and an unused flag enables a second transition of cost floor(w/2). Report the smaller distance at each target across both flags. Skip a heap entry when a shorter distance is already recorded for that same vertex and flag.

## Walk through the sample
For vertex 2, discounting the edge of weight 3 on route 1→3→2 gives 1 + 1 = 2. For vertex 4, discounting its final weight-4 edge on that route gives 3 + 1 + 2 = 6. The cheapest place to spend the discount can change with the destination.

## Complexity
The expanded graph has 2n states and at most 3m transitions. Time is O((n+m) log(n+m+1) + q), and storage is O(n+m).

## Reference implementation
~~~
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, q, s;
    cin >> n >> m >> q >> s;
    vector<vector<pair<int, int>>> g(n + 1);
    while (m--) {
        int u, v, w;
        cin >> u >> v >> w;
        g[u].emplace_back(v, w);
    }
    const long long inf = LLONG_MAX / 4;
    using State = tuple<long long, int, int>;
    priority_queue<State, vector<State>, greater<State>> open;
    vector<array<long long, 2>> d(n + 1, {inf, inf});
    auto relax = [&](int v, int used, long long cost) {
        if (cost < d[v][used]) {
            d[v][used] = cost;
            open.emplace(cost, v, used);
        }
    };
    relax(s, 0, 0);
    while (!open.empty()) {
        auto [cost, v, used] = open.top();
        open.pop();
        if (cost != d[v][used])
            continue;
        for (auto [u, w] : g[v]) {
            relax(u, used, cost + w);
            if (!used)
                relax(u, 1, cost + w / 2);
        }
    }
    while (q--) {
        int v;
        cin >> v;
        long long result = min(d[v][0], d[v][1]);
        cout << (result == inf ? -1 : result) << '\n';
    }
}
